-- Cloudflare D1 schema for GoGo. Do not migrate existing Neon rows without exporting them.
CREATE TABLE IF NOT EXISTS gogo_orders(id TEXT PRIMARY KEY,customer_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,address TEXT NOT NULL,fulfilment TEXT NOT NULL,items TEXT NOT NULL,subtotal_cents INTEGER NOT NULL,delivery_cents INTEGER NOT NULL,total_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'payment_pending',payment_id TEXT,driver_name TEXT,driver_phone TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS orders_created_idx ON gogo_orders(created_at);
CREATE TABLE IF NOT EXISTS gogo_rides(id TEXT PRIMARY KEY,booking_type TEXT NOT NULL,rider_name TEXT NOT NULL,rider_phone TEXT NOT NULL,pickup TEXT NOT NULL,destination TEXT NOT NULL,pickup_at TEXT NOT NULL,passengers INTEGER NOT NULL,vehicle_type TEXT NOT NULL,lodge_name TEXT,notes TEXT,status TEXT NOT NULL DEFAULT 'requested',driver_name TEXT,driver_phone TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gogo_lodge_partners(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,contact_name TEXT NOT NULL,contact_phone TEXT NOT NULL,area TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gogo_restaurants(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,area TEXT NOT NULL,address TEXT NOT NULL,contact_name TEXT NOT NULL,contact_phone TEXT NOT NULL,cuisine TEXT,description TEXT,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gogo_menu_items(id INTEGER PRIMARY KEY AUTOINCREMENT,restaurant_id INTEGER NOT NULL REFERENCES gogo_restaurants(id),name TEXT NOT NULL,description TEXT,price_cents INTEGER NOT NULL,available INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gogo_restaurant_orders(id TEXT PRIMARY KEY,restaurant_id INTEGER NOT NULL REFERENCES gogo_restaurants(id),customer_name TEXT NOT NULL,customer_phone TEXT NOT NULL,delivery_address TEXT NOT NULL,items TEXT NOT NULL,subtotal_cents INTEGER NOT NULL,delivery_cents INTEGER NOT NULL,total_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'requested',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS restaurant_menu_idx ON gogo_menu_items(restaurant_id);
